"use client"

import type { ReactNode } from "react"
import { useEffect, useState } from "react"
import Link from "next/link"

import { Button, buttonVariants } from "@/components/ui/button"
import {
  Sheet,
  SheetContent,
  SheetHeader,
  SheetTitle,
  SheetTrigger,
} from "@/components/ui/sheet"
import { Separator } from "@/components/ui/separator"
import { CommunitiesNav } from "@/components/tybow/communities-nav"
import type { Community } from "@/lib/schema"
import { cn } from "@/lib/utils"

export type SiteHeaderLink = {
  href: string
  label: string
}

export type SiteHeaderProps = {
  wordmark: ReactNode
  phone: string
  communities: Community[]
  nav?: SiteHeaderLink[]
  onBookTour?: () => void
  getCommunityHref?: (community: Community) => string
  overlay?: boolean
}

function telHref(phone: string) {
  return `tel:${phone.replace(/[^\d+]/g, "")}`
}

export function SiteHeader({
  wordmark,
  phone,
  communities,
  nav = [],
  onBookTour,
  getCommunityHref,
  overlay = false,
}: SiteHeaderProps) {
  const [scrolled, setScrolled] = useState(false)
  const overPhoto = overlay && !scrolled

  useEffect(() => {
    if (!overlay) {
      return
    }
    function onScroll() {
      setScrolled(window.scrollY > 24)
    }
    onScroll()
    window.addEventListener("scroll", onScroll, { passive: true })
    return () => window.removeEventListener("scroll", onScroll)
  }, [overlay])

  return (
    <header
      className={cn(
        "sticky top-0 z-50 border-b transition-colors",
        overPhoto
          ? "border-transparent bg-transparent"
          : "border-border bg-background",
      )}
    >
      <div className="mx-auto flex min-h-16 max-w-[1600px] items-center justify-between gap-4 px-4 py-3 md:px-6">
        <div className="flex min-w-0 items-center gap-8">
          <div
            className={cn(
              "font-display text-lg tracking-tight",
              overPhoto ? "text-primary-foreground" : "text-foreground",
            )}
          >
            {wordmark}
          </div>
          <nav
            className="hidden items-center gap-6 xl:flex"
            aria-label="Primary"
          >
            {nav.map((item) => (
              <Link
                key={item.href}
                href={item.href}
                className={cn(
                  "text-sm font-medium tracking-[0.12em] uppercase",
                  overPhoto
                    ? "text-primary-foreground/80 hover:text-primary-foreground"
                    : "text-muted-foreground hover:text-foreground",
                )}
              >
                {item.label}
              </Link>
            ))}
            <CommunitiesNav
              communities={communities}
              getHref={getCommunityHref}
              className={
                overPhoto ? "text-primary-foreground" : "text-muted-foreground"
              }
            />
          </nav>
        </div>

        <div className="flex shrink-0 items-center gap-3">
          <a
            href={telHref(phone)}
            className={buttonVariants({
              variant: "outline",
              className: overPhoto
                ? "border-primary-foreground/70 bg-transparent text-primary-foreground hover:bg-primary-foreground hover:text-primary"
                : undefined,
            })}
          >
            Call {phone}
          </a>
          <Button
            type="button"
            className="hidden xl:inline-flex"
            variant={overPhoto ? "secondary" : "default"}
            onClick={onBookTour}
          >
            Book a tour
          </Button>
          <Sheet>
            <SheetTrigger
              className={buttonVariants({
                variant: "ghost",
                className: overPhoto
                  ? "text-primary-foreground hover:bg-primary-foreground/10"
                  : undefined,
              })}
              aria-label="Open menu"
            >
              Menu
            </SheetTrigger>
            <SheetContent side="right" className="p-0">
              <SheetHeader>
                <SheetTitle className="font-display">{wordmark}</SheetTitle>
              </SheetHeader>
              <nav className="grid gap-2 px-4 pb-6" aria-label="Mobile">
                {nav.map((item) => (
                  <Link
                    key={item.href}
                    href={item.href}
                    className="py-2 text-foreground"
                  >
                    {item.label}
                  </Link>
                ))}
                <Separator />
                <CommunitiesNav
                  communities={communities}
                  getHref={getCommunityHref}
                  className="py-2"
                />
                <Separator />
                <a href={telHref(phone)} className="py-2 text-foreground">
                  Call {phone}
                </a>
                <Button type="button" onClick={onBookTour}>
                  Book a tour
                </Button>
              </nav>
            </SheetContent>
          </Sheet>
        </div>
      </div>
    </header>
  )
}

import Link from "next/link"

import { Badge } from "@/components/ui/badge"
import {
  communityStatusLabel,
  type Community,
  type CommunityStatus,
} from "@/lib/schema"
import { cn } from "@/lib/utils"

export type CommunitiesNavProps = {
  communities: Community[]
  getHref?: (community: Community) => string
  className?: string
}

const statusOrder: CommunityStatus[] = [
  "available",
  "selling",
  "coming-soon",
  "sold-out",
]

export function CommunitiesNav({
  communities,
  getHref = (community) => `#${community.slug}`,
  className,
}: CommunitiesNavProps) {
  const grouped = statusOrder
    .map((status) => ({
      status,
      items: communities.filter((community) => community.status === status),
    }))
    .filter((group) => group.items.length > 0)

  return (
    <details className={cn("relative", className)}>
      <summary className="cursor-pointer list-none text-sm font-medium tracking-[0.12em] text-inherit uppercase marker:content-none opacity-80 hover:opacity-100 [&::-webkit-details-marker]:hidden">
        Communities
      </summary>
      <div className="absolute top-full left-0 z-40 mt-2 w-72 rounded-lg bg-popover p-2 text-popover-foreground shadow-md ring-1 ring-foreground/10">
        {grouped.map((group) => (
          <div key={group.status} className="px-2 py-2">
            <p className="mb-1 text-xs font-bold tracking-[0.04em] text-muted-foreground uppercase">
              {communityStatusLabel[group.status]}
            </p>
            <ul>
              {group.items.map((community) => (
                <li key={community.slug}>
                  <Link
                    href={getHref(community)}
                    className="flex items-baseline justify-between gap-3 rounded-lg px-2 py-2 hover:bg-muted"
                  >
                    <span>
                      <span className="block font-medium text-foreground">
                        {community.name}
                      </span>
                      <span className="block text-xs text-muted-foreground">
                        {community.town}
                      </span>
                    </span>
                    <Badge variant="secondary">{communityStatusLabel[community.status]}</Badge>
                  </Link>
                </li>
              ))}
            </ul>
          </div>
        ))}
      </div>
    </details>
  )
}
